"""Produce a readable audit using the same C++ calculations as the site."""
import argparse
import collections
import json
import subprocess
from pathlib import Path


def generate(data_path, solver, folder):
    folder.mkdir(parents=True, exist_ok=True)
    data = json.loads(data_path.read_text(encoding='utf-8-sig'))
    result = subprocess.run([str(solver), '--semester-readout', '--data', str(data_path)], capture_output=True, encoding='utf-8', check=False)
    if result.returncode not in (0, 1):
        raise RuntimeError(result.stderr)
    (folder / 'forecast.json').write_text(result.stdout, encoding='utf-8')
    report = json.loads(result.stdout)
    clean = lambda s: str(s).replace('|', '/').replace('\n', ' ')
    lines = ['# Аудит вычитки до практики и 19 декабря', '',
             f"Расчёт на **{report['as_of_date']}**, конец семестра **{report['semester_end_date']}**. Нагрузка — из вклеек в базе, факт — подтверждённый журнал до даты расчёта. Сгенерированное расписание и классные часы не создают вычитку.", '',
             '## Что внедрено', '',
             '- Перенесены 46 групп × 52 недели: теория/ЛПЗ, УП, ПП/ПДП, экзамены и каникулы. Даты обоих листов сверены двумя независимыми парсерами.',
             '- Google-источник не изменён. СП-4611 и СП-4612п сохранены раздельно.',
             '- Обычные предметы запрещены после раннего срока и в недели без теории. Запрет действует при автоматических и ручных квотах, в обычном режиме и черновике.',
             '- Автоматические квоты учитывают остаток, совместную доступность и срочность. Уже вычитанную теорию нельзя вернуть в генерацию.',
             '- На странице «Группы» доступны импорт XLSX с проверкой перед применением, прогноз на выбранную дату, поиск предметов, фильтр 2–4 курса, причины риска и CSV.',
             '- Импорт не меняет вклейки и журнал; устаревший предпросмотр отклоняется, перед сохранением создаётся версия базы.', '',
             '## Что нельзя считать доказанным', '',
             'Доступность — верхняя оценка, а не готовое расписание всего семестра. Общие занятия считаются для каждой физической подгруппы, преподавательское время не удваивается. Время предметов пересекается: ёмкости строк нельзя складывать. Недельные объёмы календаря сверяются с вклейками отдельно; они не заменяют учебный план. Распределение УП/ПП по наставникам и рабочим местам требует отдельной проверки.', '']
    late_groups=[g['name'] for g in data['groups'] if any(w['from']=='2026-12-21' and w.get('theory_hours',0)>0 for w in g.get('academic_calendar',[]))]
    lines += [f'**Разные сроки источников:** у {len(late_groups)} групп календарь содержит теорию ещё 21–27 декабря, а заданный пользователем срок — 19 декабря (для групп с ПП ещё раньше). Эти часы нужно перенести в более ранние доступные дни. Предупреждение о недельном объёме само по себе не доказывает физическую невозможность: жёсткий предел студентов остаётся четыре пары в день.', '']
    if report.get('future_confirmed_hours'):
        lines += ['**Необходимо проверить журнал:** ' + next(i['message'] for i in report['issues'] if i['code']=='future_confirmed_ledger'),
                  'Статусы этих записей в рамках импорта календаря не изменялись. Поэтому численные дефициты ниже могут быть занижены, если будущие занятия не состоятся.', '']
    lines += ['## Группы с ранним сроком', '', '| Группа | Завершить обычные предметы до | Остаток по п/г, ч | Максимум по сетке на п/г, ч |', '|---|---|---:|---:|']
    for g in report['groups']:
        if g['early_deadline']:
            left = ' / '.join(str(p['remaining_hours']) for p in g['subgroups'])
            lines.append(f"| {clean(g['group_name'])} | {g['deadline']} | {left} | {g['capacity_hours_per_subgroup']} |")
    lines += ['', 'У ТОРД-3706 и ТОРД-3707п практика начинается 16 ноября — это исправление свежей версии источника. У ПКД-2808п смешанная неделя теории и ПП 26 апреля — 2 мая 2027 года: точный день перехода требует уточнения; до него применяется более ранняя граница недели.', '',
              '## Преподаватели с доказанным дефицитом даже по верхней оценке', '',
              'В таблице вся обычная нагрузка преподавателя, включая 1-й курс. Остаток 2–4 курса приведён отдельно и конкурирует за то же время. Это не повод автоматически менять рабочие дни без подтверждения доступности.', '',
              '| Преподаватель | Осталось обычных часов | Из них 2–4 курс | Доступно ≤ ч | Дефицит ≥ ч |', '|---|---:|---:|---:|---:|']
    names = {t['id']:t['name'] for t in data['teachers']}
    for r in report['rows']:
        if r['deadline'] == report['semester_end_date'] and not r.get('practice_deadline') and not r.get('course_year') and not r.get('group_ids'):
            cap = r['capacity_pairs_until_deadline'] * 2
            if r['remaining_regular_hours'] > cap:
                lines.append(f"| {clean(names[r['teacher']])} | {r['remaining_regular_hours']} | {r['remaining_regular_hours_course_2_4']} | {cap} | {r['remaining_regular_hours']-cap} |")
    lines += ['', 'У МЦМ-Пф-301 физически не помещаются все обычные часы до 8 ноября: нужен пересмотр распределения нагрузки/календаря, а не только увеличение приоритета решателя. По Сутягину возникает также ранний дефицит до начала ноябрьской практики.', '',
              '## Исходные данные, требующие решения', '', '| Категория | Строк / предупреждений |', '|---|---:|']
    counts=collections.Counter(i['code'] for i in report['issues'])
    categories={'teacher_missing':'Предметы без назначенного преподавателя','teacher_inactive':'Остатки у выключенных преподавателей','indivisible_remaining_hours':'Остатки не делятся на пару / обязательный двойной блок','curriculum_calendar_mismatch':'Расхождения вклеек и календаря по подгруппам','calendar_hours_shortfall':'Остаток больше недельного объёма календаря','practice_staffing_unverified':'Группы с непроверенным распределением УП/ПП'}
    for code,label in categories.items(): lines.append(f'| {label} | {counts[code]} |')
    lines += ['', 'Нечётный остаток или две лишние учебные часы при обязательном блоке 4 часа нельзя автоматически округлять вверх: это превысит вклейку. Нужны сверка факта либо отдельное разрешённое правило завершения предмета. Часы самостоятельно не увеличены и не списаны.', '',
              'Третяк и Серянина выключены в базе. У Серяниной отсутствует дата окончания отдыха. Дату выхода/замену должен задать диспетчер; одно только отсутствие в субботу не доказывает доступность с понедельника.', '',
              '## Приоритет действий', '',
              '1. Проверить будущие «подтверждённые» занятия в журнале. Импортировать как факт только прошедшие даты.',
              '2. Назначить преподавателей вакантным предметам и уточнить выход временно выключенных преподавателей.',
              '3. Сверить вклейки МЦМ-Пф-301 с календарём (по 468 часов обычных предметов на подгруппу против 288 в календаре), затем решить общий дефицит до ноября.',
              '4. Рассмотреть перераспределение предметов или подтверждённое расширение доступности преподавателей из таблицы дефицитов. Не увеличивать автоматически разрешённые четыре пары у студентов.',
              '5. Сверить неделимые остатки и отдельно спланировать УП/ПП. После каждого изменения пересчитывать прогноз на сайте.',
              '6. При каждой новой генерации использовать актуальный подтверждённый журнал; обычная публикация должна оставаться закрытой при ошибках плана.', '',
              '## Подробные причины', '']
    for i in report['issues']:
        if i['code'] == 'semester_quota_shortfall': continue
        lines.append('- ' + clean(i['message']))
    lines += ['', '## Проверки и состояние запуска', '',
              '- 25 тестов фронтенда; сборка Vite.',
              '- 6 CTest-проверок C++/API, включая атомарный импорт календаря, защиту от устаревшего предпросмотра и неизменность часов.',
              '- Отдельный запуск CP-SAT: до ПП — 3 пары поставлены; во время ПП и после возвращения за ранним сроком — отказ даже в черновике.',
              '- Суббота перепроверена: 201 пара, те же группы, преподаватели и кабинеты.',
              '- Браузерная проверка выполнена на изолированной копии базы: вход, XLSX → предпросмотр 46 групп → применение, фильтр группы, поиск предметов, перерасчёт даты, отсутствие ошибок консоли.',
              '- Исправлен годовой кэш sw.js, registerSW.js и XLSX-шаблона: неизменяемыми считаются только файлы с хешем в имени. На тестовом сайте проверены HTTP-заголовки no-cache.',
              '- Новая сборка: `.tmp/build-sep7/Release/timetable_solver.exe`. Запущенный рабочий backend ещё предыдущий: автоматическая проверка запретила его остановку и замену. До перезапуска интерфейс предупреждает о версии и не запускает генерацию старым решателем.',
              '- После закрытия старого процесса backend и старого запуска сайта запустите `scripts/start_site.ps1`: запуск теперь предпочитает новую сборку. Рабочие данные и прежние учётные данные сохранены.', '',
              'План: `docs/PRACTICE_DEADLINE_PLAN.md`. Полный машинный отчёт: `outputs/practice-audit-final/forecast.json`. Резерв до импорта: `outputs/practice-audit-final/before-live-data.json`.']
    text='\n'.join(lines)+'\n'
    (folder/'Аудит_до_19_декабря.md').write_text(text,encoding='utf-8')
    Path('docs/PRACTICE_DEADLINE_AUDIT.md').write_text(text,encoding='utf-8')
    print(json.dumps({'groups':len(report['groups']),'early_groups':sum(g['early_deadline'] for g in report['groups']),'issues':counts,'report':str(folder/'Аудит_до_19_декабря.md')},ensure_ascii=False))


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--data',type=Path,default=Path('data/timetable_data.json'));parser.add_argument('--solver',type=Path,default=Path('.tmp/build-sep7/Release/timetable_solver.exe'));parser.add_argument('--output',type=Path,default=Path('outputs/practice-audit-final'));a=parser.parse_args()
    generate(a.data.resolve(),a.solver.resolve(),a.output)
